/**
 * Agentic Workflow Designer — tool-local actions.
 *
 * Category: AI / LLM Product Management (squad S12b)
 * Tool:     Design agent workflows as a list of nodes (agent / tool / human /
 *           fallback / branch) joined to a parent workflow by workflowId.
 *
 * Agent surface: tool.agentic_workflow.*
 * Backing CRUD : workspace.agent_workflow.* + workspace.agent_node.*
 *                (both auto-generated by defineCrudActions in
 *                src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern (two collections) ────────────────────────
 * Workflows and nodes are record-keeping entities — generic create / list /
 * update / delete exist via the two workspace.* surfaces. This file adds the
 * domain verbs that span BOTH collections (the generic CRUD can't join):
 *
 *   1. list_state       — every workflow with its joined nodeCount +
 *                         nodesByKind, plus workspace totals.
 *   2. get_workflow     — one workflow joined to its nodes (null if unknown).
 *   3. create_workflow  — add a workflow shell.
 *   4. add_node         — add a node to an EXISTING workflow; refuses to
 *                         create orphans ({added:false} when workflowId is
 *                         unknown).
 *
 * Entity kinds "workspace:agentWorkflow" + "workspace:agentNode" (kindFromToolId
 * of the two CRUD toolIds) match the browser sync engine, so MCP writes
 * round-trip into the UI.
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverGetEntity, serverUpsertEntity } from "../server-store";
import type { AgentWorkflow, AgentNode } from "@/lib/stores/workspace-types";

const KIND_WORKFLOW = "workspace:agentWorkflow";
const KIND_NODE = "workspace:agentNode";

const NODE_KINDS = ["agent", "tool", "human", "fallback", "branch"] as const;
const NodeKindSchema = z.enum(NODE_KINDS);

const ws = () => useWorkspaceStore.getState();

/** Empty per-kind tally — initialised for every kind so callers can index
 *  nodesByKind.fallback without an existence check. */
function emptyKindTally(): Record<AgentNode["kind"], number> {
  return { agent: 0, tool: 0, human: 0, fallback: 0, branch: 0 };
}

function summarize(workflows: AgentWorkflow[], nodes: AgentNode[]) {
  // Pre-bucket nodes by workflowId in one pass so the per-workflow join is
  // O(nodes) total rather than O(workflows × nodes).
  const nodesByWorkflow = new Map<string, AgentNode[]>();
  for (const n of nodes) {
    const arr = nodesByWorkflow.get(n.workflowId) ?? [];
    arr.push(n);
    nodesByWorkflow.set(n.workflowId, arr);
  }
  return {
    totalWorkflows: workflows.length,
    totalNodes: nodes.length,
    workflows: workflows.map((w) => {
      const wn = nodesByWorkflow.get(w.id) ?? [];
      const nodesByKind = emptyKindTally();
      for (const n of wn) if (n.kind in nodesByKind) nodesByKind[n.kind] += 1;
      return {
        id: w.id,
        name: w.name,
        description: w.description,
        nodeCount: wn.length,
        nodesByKind,
      };
    }),
  };
}

// ──────── tool.agentic_workflow.list_state ────────
registry.register({
  id: "tool.agentic_workflow.list_state",
  toolId: "tool.agentic_workflow",
  name: "list_state",
  category: "read",
  description:
    "List every agent workflow with its joined node summary. Returns {totalWorkflows, totalNodes, workflows: {id, name, description, nodeCount, nodesByKind: {agent, tool, human, fallback, branch}}[]}.",
  paramsSchema: z.object({}),
  handler: async () => summarize(ws().agentWorkflows ?? [], ws().agentNodes ?? []),
  mcpHandler: async (_params, ctx) => {
    const [workflows, nodes] = await Promise.all([
      serverListEntities<AgentWorkflow>(ctx.userId, KIND_WORKFLOW),
      serverListEntities<AgentNode>(ctx.userId, KIND_NODE),
    ]);
    return summarize(workflows, nodes);
  },
});

// ──────── tool.agentic_workflow.get_workflow ────────
registry.register({
  id: "tool.agentic_workflow.get_workflow",
  toolId: "tool.agentic_workflow",
  name: "get_workflow",
  category: "read",
  description:
    "Fetch one workflow joined to its nodes. Returns {workflow, nodes} or null when the id is unknown.",
  paramsSchema: z.object({ id: z.string() }),
  handler: async (params) => {
    const workflow = (ws().agentWorkflows ?? []).find((w) => w.id === params.id);
    if (!workflow) return null;
    const nodes = (ws().agentNodes ?? []).filter((n) => n.workflowId === params.id);
    return { workflow, nodes };
  },
  mcpHandler: async (params, ctx) => {
    const workflow = await serverGetEntity<AgentWorkflow>(ctx.userId, KIND_WORKFLOW, params.id);
    if (!workflow) return null;
    const allNodes = await serverListEntities<AgentNode>(ctx.userId, KIND_NODE);
    return { workflow, nodes: allNodes.filter((n) => n.workflowId === params.id) };
  },
});

// ──────── tool.agentic_workflow.create_workflow ────────
registry.register({
  id: "tool.agentic_workflow.create_workflow",
  toolId: "tool.agentic_workflow",
  name: "create_workflow",
  category: "write",
  requiresConfirmation: false,
  description:
    "Create an empty agent workflow. Returns {added: true, id} — add nodes with add_node.",
  paramsSchema: z.object({
    name: z.string().min(1).max(200),
    description: z.string().max(2000).optional(),
  }),
  handler: async (params) => {
    const wf: AgentWorkflow = {
      id: crypto.randomUUID(),
      name: params.name,
      description: params.description,
    };
    ws().upsertAgentWorkflow(wf);
    return { added: true, id: wf.id };
  },
  mcpHandler: async (params, ctx) => {
    const wf: AgentWorkflow = {
      id: crypto.randomUUID(),
      name: params.name,
      description: params.description,
    };
    await serverUpsertEntity<AgentWorkflow>(ctx.userId, KIND_WORKFLOW, wf);
    return { added: true, id: wf.id };
  },
});

// ──────── tool.agentic_workflow.add_node ────────
// Refuses to create orphan nodes — a node whose workflowId points at nothing
// would never render in the designer and would skew list_state's join. The
// agent must create_workflow first. Additive → no confirmation.
registry.register({
  id: "tool.agentic_workflow.add_node",
  toolId: "tool.agentic_workflow",
  name: "add_node",
  category: "write",
  requiresConfirmation: false,
  description:
    "Add a node to an EXISTING workflow. kind is agent | tool | human | fallback | branch. `next` lists downstream node ids. Returns {added: false} when workflowId is unknown (orphan nodes are refused), else {added: true, id}.",
  paramsSchema: z.object({
    workflowId: z.string(),
    label: z.string().min(1).max(200),
    kind: NodeKindSchema,
    description: z.string().max(2000).optional(),
    next: z.array(z.string()).optional(),
  }),
  handler: async (params) => {
    const exists = (ws().agentWorkflows ?? []).some((w) => w.id === params.workflowId);
    if (!exists) return { added: false };
    const node: AgentNode = {
      id: crypto.randomUUID(),
      workflowId: params.workflowId,
      label: params.label,
      kind: params.kind,
      description: params.description,
      next: params.next,
    };
    ws().upsertAgentNode(node);
    return { added: true, id: node.id };
  },
  mcpHandler: async (params, ctx) => {
    const workflow = await serverGetEntity<AgentWorkflow>(
      ctx.userId,
      KIND_WORKFLOW,
      params.workflowId
    );
    if (!workflow) return { added: false };
    const node: AgentNode = {
      id: crypto.randomUUID(),
      workflowId: params.workflowId,
      label: params.label,
      kind: params.kind,
      description: params.description,
      next: params.next,
    };
    await serverUpsertEntity<AgentNode>(ctx.userId, KIND_NODE, node);
    return { added: true, id: node.id };
  },
});
